{"command": "python3 << 'EOF'
from rdkit import Chem

# Parse the input molecule
smiles = "C/C(=C\\c1ccccc1)c1ccc2c(c1)C(C)(C)C(O)C2(C)C"
mol = Chem.MolFromSmiles(smiles)

if mol:
    print("Molecule parsed successfully")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Find functional groups
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 8:  # Oxygen
            print(f"Oxygen at position {atom.GetIdx()}: bonded to {len(list(atom.GetNeighbors()))} neighbors")
            for neighbor in atom.GetNeighbors():
                print(f"  - Bonded to C{neighbor.GetIdx()} (atomic num {neighbor.GetAtomicNum()})")

    # Check for double bonds
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.DOUBLE:
            print(f"Double bond between C{bond.GetBeginAtomIdx()} and C{bond.GetEndAtomIdx()}")
            print(f"  Stereochemistry: {bond.GetStereo()}")

    # Try to identify the alcohol carbon
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 8:
            neighbors = list(atom.GetNeighbors())
            if len(neighbors) == 1:
                carbon = neighbors[0]
                print(f"\nAlcohol oxygen attached to C{carbon.GetIdx()}")
                print(f"C{carbon.GetIdx()} has {carbon.GetTotalNumHs()} hydrogens")
                print(f"C{carbon.GetIdx()} is bonded to {len(list(carbon.GetNeighbors()))} carbons")

                # Get the neighbors of this carbon
                for n in carbon.GetNeighbors():
                    if n.GetAtomicNum() == 8:
                        continue
                    print(f"  - C{n.GetIdx()}")
else:
    print("Failed to parse molecule")
EOF
